using System;using System.Drawing;using System.IO;using TavernLens;
class CardCheck{static Entity Unit(string id,int a,int h,params string[] effects){var u=new Entity{CardId=id};u.Tags["ATK"]=a.ToString();u.Tags["HEALTH"]=h.ToString();foreach(var e in effects)u.Tags[e]="1";return u;}static void Main(string[] args){Store.Root=args.Length>0?Path.GetFullPath(args[0]):AppDomain.CurrentDomain.BaseDirectory;var units=new[]{Unit("BG29_888",3,9),Unit("BG34_140",3,4,"DIVINE_SHIELD","TAUNT"),Unit("BG29_888_G",125,249,"DIVINE_SHIELD","REBORN","VENOMOUS"),Unit("BG34_140",20,30,"TAUNT","REBORN","VENOMOUS","DEATHRATTLE")};units[3].Tags["DAMAGE"]="7";if(RecordedCard.Health(units[3])!=23)throw new Exception("Damage");if(RecordedCard.Effects(units[0]).Length!=0)throw new Exception("False effects");if(RecordedCard.Effects(units[2]).Length!=3)throw new Exception("Effects");units[1].Tags["REBORN"]="0";if(Array.IndexOf(RecordedCard.Effects(units[1]),"REBORN")>=0)throw new Exception("Consumed effect");using(var canvas=new Bitmap(760,300)){using(var g=Graphics.FromImage(canvas)){g.Clear(Color.FromArgb(27,34,44));for(int i=0;i<units.Length;i++)using(var art=Image.FromFile(Path.Combine(Store.Data,"art","verified-v2","251951",units[i].CardId+".png")))RecordedCard.Draw(g,art,new Rectangle(10+i*185,10,170,260),units[i],i==2);}canvas.Save(Path.Combine(Path.GetTempPath(),"TavernLens-recorded-card-preview.png"));}Console.WriteLine("Recorded stats and effect selection checks passed");}}

